func TestGrant_SameRequestID(t *testing.T) {
	db := testdb.New(t)
	svc := NewService(db)

	first, err := svc.Grant(ctx, GrantRequest{
		UserID:     9001,
		ActivityID: "20261018_autumn",
		RequestID:  "req-7f3a91",
	})
	if err != nil {
		t.Fatalf("first grant: %v", err)
	}
	if first.Replayed {
		t.Fatalf("first grant should not be replayed")
	}

	second, err := svc.Grant(ctx, GrantRequest{
		UserID:     9001,
		ActivityID: "20261018_autumn",
		RequestID:  "req-7f3a91",
	})
	if err != nil {
		t.Fatalf("replay grant: %v", err)
	}
	if !second.Replayed {
		t.Fatalf("second grant should be replayed")
	}
	if second.GrantID != first.GrantID {
		t.Fatalf("grant id changed: %d -> %d", first.GrantID, second.GrantID)
	}
	if n := testdb.CountGrants(t, db, 9001, "20261018_autumn"); n != 1 {
		t.Fatalf("coupon_grant rows = %d, want 1", n)
	}
}

// Grant 处理 POST /api/coupon/grant。
func (h *Handler) Grant(c *gin.Context) {
	var req grantRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, errorBody{Code: "invalid_body", Message: err.Error()})
		return
	}
	req.RequestID = strings.TrimSpace(req.RequestID)
	if req.RequestID == "" {
		req.RequestID = strings.TrimSpace(c.GetHeader("X-Request-Id"))
	}
	if req.RequestID == "" {
		c.JSON(http.StatusBadRequest, errorBody{
			Code:    "missing_request_id",
			Message: "request_id 不能为空",
		})
		return
	}
	if len(req.RequestID) > 64 {
		c.JSON(http.StatusBadRequest, errorBody{
			Code:    "invalid_request_id",
			Message: "request_id 超过 64 个字符",
		})
		return
	}
	result, err := h.grant.Grant(c.Request.Context(), coupon.GrantRequest{
		UserID:     c.GetInt64(ctxUserID),
		ActivityID: req.ActivityID,
		RequestID:  req.RequestID,
	})
	if err != nil {
		h.writeGrantError(c, err)
		return
	}
	c.JSON(http.StatusOK, grantResponse{
		GrantID:  result.GrantID,
		Status:   result.Status,
		Replayed: result.Replayed,
	})
}

// Grant 只发一条 INSERT，是否重复交给 uk_user_activity_request 裁决。
func (s *Service) Grant(ctx context.Context, req GrantRequest) (GrantResult, error) {
	if req.RequestID == "" {
		return GrantResult{}, ErrMissingRequestID
	}

	now := s.clock.Now()
	row := GrantRow{
		UserID:     req.UserID,
		ActivityID: req.ActivityID,
		RequestID:  req.RequestID,
		Status:     StatusIssued,
		CreatedAt:  now,
	}
	grantID, err := s.store.Insert(ctx, row)
	if errors.Is(err, ErrDuplicateKey) {
		return s.resolveExisting(ctx, req)
	}
	if err != nil {
		return GrantResult{}, fmt.Errorf("insert coupon_grant: %w", err)
	}

	s.publishIssued(ctx, grantID, row)
	return GrantResult{GrantID: grantID, Status: StatusIssued}, nil
}

// resolveExisting 在同一次请求已经落库时，返回首发的记录。
func (s *Service) resolveExisting(ctx context.Context, req GrantRequest) (GrantResult, error) {
	row, err := s.store.FindByRequest(ctx, req.UserID, req.ActivityID, req.RequestID)
	if err != nil {
		return GrantResult{}, fmt.Errorf("find coupon_grant by request: %w", err)
	}
	if row == nil {
		// 唯一索引报了冲突却读不到行，说明回读键与索引不一致，不能当成成功。
		return GrantResult{}, ErrIdempotencyMismatch
	}
	s.logger.Info("coupon grant replayed",
		"grant_id", row.ID,
		"user_id", row.UserID,
		"activity_id", row.ActivityID,
		"request_id", row.RequestID,
	)
	return GrantResult{
		GrantID:  row.ID,
		Status:   row.Status,
		Replayed: true,
	}, nil
}

// IsDuplicateKey 把 MySQL 1062 翻译成哨兵错误，业务层不必依赖驱动类型。
func IsDuplicateKey(err error) bool {
	var mysqlErr *mysql.MySQLError
	if !errors.As(err, &mysqlErr) {
		return false
	}
	return mysqlErr.Number == 1062
}

func TestGrant_ConcurrentSameRequest(t *testing.T) {
	db := testdb.New(t)
	svc := NewService(db)

	const n = 20
	var wg sync.WaitGroup
	ids := make([]int64, n)
	errs := make([]error, n)
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			res, err := svc.Grant(ctx, GrantRequest{
				UserID:     9002,
				ActivityID: "20261018_autumn",
				RequestID:  "req-concurrent-1",
			})
			ids[i], errs[i] = res.GrantID, err
		}(i)
	}
	wg.Wait()

	for i := 0; i < n; i++ {
		if errs[i] != nil {
			t.Fatalf("goroutine %d: %v", i, errs[i])
		}
		if ids[i] != ids[0] {
			t.Fatalf("goroutine %d got grant %d, want %d", i, ids[i], ids[0])
		}
	}
	if got := testdb.CountGrants(t, db, 9002, "20261018_autumn"); got != 1 {
		t.Fatalf("coupon_grant rows = %d, want 1", got)
	}
}

// publishIssued 只在首次落库后调用，重放路径不会进来。
// marketing-service 按 grant_id 去重，重复事件会变成重复通知。
func (s *Service) publishIssued(ctx context.Context, grantID int64, row GrantRow) {
	evt := CouponIssued{
		GrantID:    grantID,
		UserID:     row.UserID,
		ActivityID: row.ActivityID,
		IssuedAt:   row.CreatedAt,
	}
	if err := s.publisher.Publish(ctx, "coupon-issued", evt); err != nil {
		s.logger.Warn("publish coupon-issued failed",
			"grant_id", grantID,
			"activity_id", row.ActivityID,
			"err", err,
		)
		s.metrics.Counter("coupon_issued_publish_failed").Inc()
	}
}
